import{_ as r,a0 as e,w as d,s as u,I as l,x as i,a1 as t,A as a,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Fuchsia 對 Android 意味着什麼 | LCTT x X-CMD","titleTemplate":false,"description":"Fuchsia 對 Android 意味着什麼 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fuchsia 對 Android 意味着什麼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fuchsia 對 Android 意味着什麼 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170516 What Fuchsia could mean for Android","title":"Fuchsia 對 Android 意味着什麼","tag":"201706","desc":""},"relativePath":"201706/20170516 What Fuchsia could mean for Android.md","filePath":"[post].md"}'),p={name:"201706/20170516 What Fuchsia could mean for Android.md"};function m(f,o,g,h,x,b){const n=e("Link");return d(),u("div",null,[o[19]||(o[19]=l("h1",{id:"fuchsia-對-android-意味着什麼",tabindex:"-1"},[i("Fuchsia 對 Android 意味着什麼 "),l("a",{class:"header-anchor",href:"#fuchsia-對-android-意味着什麼","aria-label":"Permalink to “Fuchsia 對 Android 意味着什麼”"},"​")],-1)),o[20]||(o[20]=l("p",null,"Fuchsia 可能是下個會替代 Android 或 Chrome OS 的系統。猜測有很多，Jack Wallen 對此補充了一些給 Google 的讚譽和告誡。",-1)),o[21]||(o[21]=l("p",null,[l("img",{src:"https://tr1.cbsistatic.com/hub/i/r/2017/05/16/d2a51714-2cd0-4fd5-9639-a6f2f8140c2e/resize/770x/10063b88bf93990b65e5d14ee33a0aac/fuchsiahero.jpg",alt:"fuchsiahero.jpg"})],-1)),o[22]||(o[22]=l("p",null,"Image: Jack Wallen",-1)),l("p",null,[o[1]||(o[1]=i("Google 總是以 “Google” 的方式解決或者做某件事。因此，當他們開始做一個讓很多人撓頭的項目時，大家是不覺得奇怪的。該項目被稱為 ",-1)),t(n,{href:"https://github.com/fuchsia-mirror"},{default:a(()=>[...o[0]||(o[0]=[i("Fuschia",-1)])]),_:1}),o[2]||(o[2]=i("，大多數密切關注 Google 和 Android 的人都知道這個新平台。",-1))]),o[23]||(o[23]=s('<p>對於那些還沒緊跟 Google 最新消息的用户而言，Fuschia 是一個新的、開源的實時操作系統，它首先出現於 2016 年 8 月。那時，Fuchsia 只不過是一個命令列。一年不到的時間過去了，這個平台已經有了一個相當有趣的 GUI。</p><p>可能最讓 Linux 擁躉失望的是，Fuchsia 並沒有使用 Linux 內核。這個項目完全是 Google 開發的，使用了 Google 開發的名為 “Magenta”微內核。他們為什麼這麼做？瞭解到 Google 的最新設備 Pixel 運行的內核是 Linux 內核 3.18，你就會有你自己的答案了。Linux 3.18 發佈於 2014 年（也就是説，在技術上已經過時了）。既然這樣，為什麼 Google 不能自己完全單幹，以便儘可能地保持他們的移動平台跟上最新發展？</p><p>儘管我不願意承認 Linux 可能不會（在未來的某個時期）成為全球最廣泛使用的生態系統，但我相信這是 Google 的正確舉措，不過我有一個重要的告誡。</p><h3 id="首先-一些讚譽" tabindex="-1">首先，一些讚譽 <a class="header-anchor" href="#首先-一些讚譽" aria-label="Permalink to “首先，一些讚譽”">​</a></h3><p>首先我必須説，Google 開源 Fuchsia 這事真棒。Android 已經從開源的 Linux 內核中受益多年，所以這促使了 Google 開放他們最新的項目。説實話，如果不是開源和 Linux 內核，Android 就不會發展得那麼快了。事實上，我大膽猜測，如果 Android 沒有 Linux 和開源的支持，現在移動市場份額會顯示出非常不同的、由蘋果制定的結果。</p><p>一些喝彩是有必要的。操作系統不時需要完全重新思考。Android 是一個為移動平台服務得很好的令人驚奇的平台。然而，走到現在也就差不多了。考慮到消費界一直在尋找下一個大事件，而 Android（和 iOS）的潛力已盡榨乾。與一個嚴重過時的內核相比，還是準備迎接對 Fuchsia 的喜愛吧。</p><p>谷歌從來不會停滯不前，這個新平台是證明。</p><h3 id="一個十足的告誡" tabindex="-1">一個十足的告誡 <a class="header-anchor" href="#一個十足的告誡" aria-label="Permalink to “一個十足的告誡”">​</a></h3><p>開始這部分之前，我需要先給大家展示我的開源背景。自從 90 年代末以來，我一直是 Linux 的用户，並幾乎涉及了開源的各個方面。在過去幾年中，我一直在關注 Ubuntu 的發展，並對他們（現在）失敗的融合嘗試發表過看法。換言之，這也是我對 Fuchsia 的擔心。</p><p>我認為 Google 對 Fucshia 的大計劃是創建一個面對所有設備的操作系統：智能手機、IoT、Chromebook。從表面看來，這聽起來像是一個會有重大成果的想法。但是，如果你看過 Canonical 對 Unity 8/Mir 融合的努力，你就會對“一個平台統治所有”的想法感到畏懼。當然這並不完全相同。我覺得 Google 正在創建一個單一的平台，讓你 “融合” 所有的設備。畢竟，智能手機與物聯網融合有什麼好處？我們不需要在手機和恆温器之間交換數據。對麼？對麼？？？</p><p>即使如此，這應該是谷歌的計劃，我會提醒他們近距離了解下 Canonical 和 Unity 8 之間發生的事。想法很好，但根本無法實現。</p>',11)),l("p",null,[o[4]||(o[4]=i("我也有可能錯了。Google 可能只是將 Fuchsia 看作是 Android 的替代品。這很可能是 Google 需要替換過時的 Linux 內核，並決定“把一切都包含進來”。但是考慮到 Armadillo（Fuchsia UI）由跨平台的 ",-1)),t(n,{href:"https://flutter.io/"},{default:a(()=>[...o[3]||(o[3]=[i("Flutter SDK",-1)])]),_:1}),o[5]||(o[5]=i(" 編寫，跨越平台邊界的想法就有了可能。",-1))]),o[24]||(o[24]=l("p",null,"或者，也許 Fuchsia 只是谷歌説的 “讓我們用今天所知道的知識重建我們的智能手機平台，看看它會走向何方”。如果是這樣，我可以想像，Google 移動操作系統將會取得重大成功。然而，現實情況是，人們必須面對的是“一個平台統治所有”還有許多要解決的事情。Google 已經在 Chromebook 上測試 Android app 很長時間了。不幸的是，這個思路一直反響平平（最多如此）。隨着微軟以自己的方式來直面 Chromebook，Google 知道他們必須擴大生態系統，否則將會失去寶貴的領地（如在教育領域）。要解決這個問題的一種方法是使用單個操作系統來驅動智能手機和 Chromebook。這意味着所有的程序都可以在兩個平台（這是一個重要的福音）運行以及生態系統的普遍性（再一次，這是巨大的福音）。",-1)),o[25]||(o[25]=l("h3",{id:"猜測",tabindex:"-1"},[i("猜測 "),l("a",{class:"header-anchor",href:"#猜測","aria-label":"Permalink to “猜測”"},"​")],-1)),o[26]||(o[26]=l("p",null,"Google 對會引發很多行家的猜測的事情一直小心謹慎。一般來説，至少對於 Android，谷歌似乎一直都在做出正確的選擇。如果他們相信 Fuchsia 是要走的路，那麼我就傾向於相信他們。然而，圍繞這個平台有如此多的不確定性會讓人們一直迫切地要知道。",-1)),o[27]||(o[27]=l("p",null,"那你怎麼看？Fuchsia 會成為什麼？和我一起猜猜看。",-1)),o[28]||(o[28]=l("hr",null,null,-1)),o[29]||(o[29]=l("p",null,"作者簡介：",-1)),o[30]||(o[30]=l("p",null,"Jack Wallen 是 TechRepublic 和 Linux.com 的獲獎作家。他是開源的狂熱倡導者, 也是 The Android Expert 的代言人。有關 Jack Wallen 的更多消息，請訪問他的網站 jackwallen.com。",-1)),o[31]||(o[31]=l("hr",null,null,-1)),l("p",null,[o[7]||(o[7]=i("via: ",-1)),t(n,{href:"http://www.techrepublic.com/article/what-fuchsia-could-mean-for-android/"},{default:a(()=>[...o[6]||(o[6]=[i("http://www.techrepublic.com/article/what-fuchsia-could-mean-for-android/",-1)])]),_:1})]),l("p",null,[o[11]||(o[11]=i("作者：",-1)),t(n,{href:"http://www.techrepublic.com/article/what-fuchsia-could-mean-for-android/#modal-bio"},{default:a(()=>[...o[8]||(o[8]=[i("Jack Wallen",-1)])]),_:1}),o[12]||(o[12]=i(" 譯者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:a(()=>[...o[9]||(o[9]=[i("geekpi",-1)])]),_:1}),o[13]||(o[13]=i(" 校對：",-1)),t(n,{href:"https://github.com/jasminepeng"},{default:a(()=>[...o[10]||(o[10]=[i("jasminepeng",-1)])]),_:1})]),l("p",null,[o[16]||(o[16]=i("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...o[14]||(o[14]=[i("LCTT",-1)])]),_:1}),o[17]||(o[17]=i(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:a(()=>[...o[15]||(o[15]=[i("Linux中國",-1)])]),_:1}),o[18]||(o[18]=i(" 榮譽推出",-1))])])}const C=r(p,[["render",m]]);export{T as __pageData,C as default};
